mapper.select:
SELECT

FROM bank_transaction
WHERE linked_account_id = #{linkedAccountId}
AND external_transaction_id = #{externalTransactionId}

mapper.update:
UPDATE bank_transaction
SET processing_status = #{nextStatus}
WHERE bank_transaction_id = #{bankTransactionId}
AND processing_status = #{currentStatus}

mapper.sql:
WHERE linked_account_id = #{linkedAccountId}

    AND processing_status = #{condition.processingStatus}


    AND transaction_type = #{condition.transactionType}


    AND (
    counterparty_name LIKE CONCAT('%', #{condition.keyword}, '%')
    OR memo LIKE CONCAT('%', #{condition.keyword}, '%')
    )


    AND transaction_at >= #{condition.fromDate}


    AND transaction_at < DATE_ADD(#{condition.toDate}, INTERVAL 1 DAY)
